    "question": "什么是环形分配器和功率放大电路",
    "answer": "环形分配器：将数控装置送来的一串指令脉冲，按步进电机所要求的通电顺序分配给步进电机驱动电源的各相输入端，以控制励磁绕组的通断，实现步进电机的运行及换向 功率放大电路：将环形分配器送来的弱电信号放大，以得到步进电机绕组所需的脉冲电流及脉冲波形"
