    "question": "普通数控机床和加工中心的区别？（机械制造技术基础）",
    "answer": "①加工中心是备有刀库并能自动更换刀具，而数控机床没有 ②能对工件进行多工序集中加工，而数控机床用来完成零件一个工序的自动化循环加工 ③加工中心适用范围广，加工精度高，生产率高。而 NC 常用在零件复杂程度不高、精度较高，品种多变的生产场合"
